+// Read by `prerender-notebook.mjs`'s own filesystem path, not a static `import ... from
+// "*.json"` — a static import would fail the whole build if the file is missing (e.g. a dev who
+// skipped `npm run prerender:notebook`), whereas this degrades gracefully: `initialResponse` is
+// `undefined`, and `GramaireNotebookIsland` just falls back to its normal loading-placeholder +
+// evaluate-on-mount behavior (identical to how `/notebook` already works with no `initial` prop).
+// `process.cwd()`, not `import.meta.url` — verified empirically that during `astro build`,
+// this file's own `import.meta.url` resolves to an Astro-internal scratch path
+// (`dist/.prerender/...`), not this file's real source location, so a relative URL from it
+// doesn't reach the generated JSON. `astro build`/`astro dev` are always run from `site/`
+// (every script and CI workflow `cd`s or sets `working-directory: site` first), so cwd is stable.
+let initialResponse: LabResponse | undefined;
+try {
+  const generatedPath = path.join(
